// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Recorder rec;

    function setUp() public { c = new airPort(); rec = new Recorder(); }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(v > 0);

        uint256 before = rec.callCount();
        bool ok; try c.transfer(from, address(rec), _normalize(tos), v) { ok = true; } catch { ok = false; }
        assertTrue(ok == (tos.length > 0 && rec.callCount() > before));
    }

    function _normalize(address[] memory tos) internal pure returns (address[] memory) {
        return tos;
    }
}

contract Recorder {
    uint256 public callCount;
    bytes public lastData;

    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        lastData = msg.data;
        return true;
    }

    fallback() external payable {
        callCount++;
        lastData = msg.data;
    }

    receive() external payable {
        callCount++;
    }
}
